#include "dataProcessor.h"

/* PNG */
static const wxString s_dataProcessor_64_png = wxT("");

wxIcon ibValueMetaObjectDataProcessor::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectDataProcessor::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_dataProcessor_64_png, wxSize(16, 16));

	return icon;
}
